using Xunit;

namespace RecursiveAI.OneLite.Tests.Engine;

/// <summary>
/// Features of the pinned shell that are built in beyond the core SQL functions: the percentile aggregates (median, percentile, percentile_cont,
/// percentile_disc, also as window functions), json_group_array and json_group_object as window functions, row values compared with and
/// assigned from subqueries of several columns, and the auxiliary functions of FTS and R*Tree called where they cannot work. Expected texts
/// were recorded from the pinned sqlite3 3.53.4 (rows joined with '|' and a line break, NULL as nothing, errors as "Error: " and the message).
/// </summary>
public sealed class RowValueAndPercentileTests
{
    private const string Setup = "create table t(a,b); insert into t values(1,10),(2,20),(3,5),(4,null),(5,'x'),(2,7); create table n(v); insert into n values(1),(2),(3),(4),(10); create table e(v); create table c(x text collate nocase, y); insert into c values('a',1),('B',2); create table c2(z text collate nocase); insert into c2 values('A'); create table ty(i integer, tx text, r real); insert into ty values(1,'2',3.0),(10,'x',4);";

    private const string DmlSetup = "create table rv1(a,b,c); insert into rv1 values(1,2,3); create table rv2(a integer primary key, b, c); insert into rv2 values(1,2,3),(2,3,4),(3,4,5);";

    private const string FtsSetup = "create virtual table f using fts5(c); insert into f values('hello world'); create virtual table g using fts4(c); insert into g values('hello world'); create virtual table rt using rtree(id,a,b); create table nr(a);";

